<?php declare(strict_types=1); require_once dirname(__DIR__) . "/src/autoload.php"; $p = (new AquiHayTema\Engine\PartidaService(getcwd()))->nuevaPartida("juego_v1", "t"); echo "ucui: " . ($p["reloj"]["ultimo_catch_up_iso"] ?? "NONE") . PHP_EOL; echo "usi: " . ($p["reloj"]["ultima_sesion_iso"] ?? "NONE") . PHP_EOL; $p["reloj"]["ultimo_catch_up_iso"] = (new DateTimeImmutable("-5 hours", new DateTimeZone("UTC")))->format(DATE_ATOM); echo "ucui after: " . $p["reloj"]["ultimo_catch_up_iso"] . PHP_EOL; $r = AquiHayTema\Engine\CatchUpEngine::ejecutarAlCargar($p, getcwd()); echo "EJECUTADO: " . (($r["ejecutado"] ?? false) ? "YES" : "NO") . PHP_EOL; echo "NOTA: " . ($r["nota"] ?? "none") . PHP_EOL; echo "STATS: " . json_encode($r["stats"] ?? "NONE") . PHP_EOL;